import { Controller, Get, Post, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUSES = ['진행', '완료', '취소'];

const COLS =
  'asset_inspection_id AS "assetInspectionId", ' +
  'asset_inspection_plan_id AS "assetInspectionPlanId", ' +
  'fixed_asset_id AS "fixedAssetId", ' +
  'inspection_status AS "inspectionStatus", ' +
  'inspection_result AS "inspectionResult", ' +
  'inspected_at AS "inspectedAt"';

function idOf(value: unknown): string {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '요청 값의 형식이 올바르지 않습니다.');
  }
  return text;
}

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '실사 결과는 글자여야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr02506Controller {
  @Post('/asset-inspections')
  @HttpCode(200)
  async createAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const planId = idOf(data['assetInspectionPlanId']);
    const assetId = idOf(data['fixedAssetId']);
    const result = optionalText(data['inspectionResult']);
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (plans[0]['approvalStatus'] !== '승인') {
        throw new ApiError(409, 'INSPECTION_PLAN_NOT_APPROVED', '승인되지 않은 실사계획입니다.');
      }
      const assets = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE fixed_asset_id = CAST(:assetId AS bigint)',
        { assetId },
      );
      if (assets.length === 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '고정자산을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT asset_inspection_id FROM asset_inspection WHERE asset_inspection_plan_id = CAST(:planId AS bigint) AND fixed_asset_id = CAST(:assetId AS bigint)',
        { planId, assetId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '이미 해당 실사계획에 등록된 자산입니다.');
      }
      // 가정: 실사 시작 시 상태는 '진행'
      const rows = await db.query(
        'INSERT INTO asset_inspection (asset_inspection_plan_id, fixed_asset_id, inspection_status, inspection_result, created_at, updated_at) ' +
          "VALUES (CAST(:planId AS bigint), CAST(:assetId AS bigint), '진행', :result, now(), now()) " +
          'RETURNING asset_inspection_id AS "assetInspectionId", inspection_status AS "inspectionStatus"',
        { planId, assetId, result },
      );
      return rows[0];
    });
  }

  @Get('/asset-inspections')
  async listAssetInspections(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const query = checks.queryOf(req.query);
    const planRaw = query['assetInspectionPlanId'];
    const planId = planRaw === undefined || planRaw === '' ? null : idOf(planRaw);
    const statusRaw = query['inspectionStatus'];
    const status = statusRaw === undefined || statusRaw === '' ? null : String(statusRaw);
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실사 상태가 올바르지 않습니다.');
    }
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    let size = sizeRaw === undefined || sizeRaw === '' ? DEFAULT_SIZE : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
    }
    size = Math.min(size, MAX_SIZE);
    const offset = page * size;
    return transaction(async (db) => {
      const where =
        ' WHERE (CAST(:planId AS bigint) IS NULL OR asset_inspection_plan_id = CAST(:planId AS bigint))' +
        ' AND (CAST(:status AS varchar) IS NULL OR inspection_status = CAST(:status AS varchar))';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM asset_inspection' + where,
        { planId, status },
      );
      const items = await db.query(
        'SELECT ' + COLS + ' FROM asset_inspection' + where +
          ' ORDER BY asset_inspection_id DESC LIMIT :size OFFSET :offset',
        { planId, status, size, offset },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/asset-inspections/:assetInspectionId/complete')
  @HttpCode(200)
  async completeAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = idOf(req.params['assetInspectionId']);
    const data = checks.inputOf(req.body);
    const result = optionalText(data['inspectionResult']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT inspection_status AS "inspectionStatus", inspection_result AS "inspectionResult", fixed_asset_id AS "fixedAssetId" ' +
          'FROM asset_inspection WHERE asset_inspection_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'INSPECTION_NOT_FOUND', '실사정보를 찾을 수 없습니다.');
      }
      if (rows[0]['inspectionStatus'] !== '진행') {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '진행 중이 아닌 실사는 완료 처리할 수 없습니다.');
      }
      const finalResult = result ?? (rows[0]['inspectionResult'] as string | null);
      if (finalResult === null || finalResult === undefined || finalResult === '') {
        throw new ApiError(400, 'VALIDATION_FAILED', '실사 결과를 입력해야 완료할 수 있습니다.');
      }
      await db.execute(
        "UPDATE asset_inspection SET inspection_status = '완료', inspection_result = :result, inspected_at = now(), updated_at = now() " +
          'WHERE asset_inspection_id = CAST(:id AS bigint)',
        { id, result: finalResult },
      );
      // 가정: 실사 결과의 자산정보 반영은 자산 변동현황(asset_change)에 이력으로 남긴다 (결재 비연계 건이라 상태는 기안)
      await db.execute(
        'INSERT INTO asset_change (fixed_asset_id, change_type, change_date, change_content, change_status, created_at, updated_at) ' +
          "VALUES (CAST(:assetId AS bigint), '자산실사', CAST(now() AS date), :content, '기안', now(), now())",
        { assetId: String(rows[0]['fixedAssetId']), content: finalResult },
      );
      return { inspectionStatus: '완료' };
    });
  }

  @Post('/asset-inspections/:assetInspectionId/cancel')
  @HttpCode(200)
  async cancelAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = idOf(req.params['assetInspectionId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT inspection_status AS "inspectionStatus" FROM asset_inspection WHERE asset_inspection_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'INSPECTION_NOT_FOUND', '실사정보를 찾을 수 없습니다.');
      }
      if (rows[0]['inspectionStatus'] !== '진행') {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '진행 중이 아닌 실사는 취소할 수 없습니다.');
      }
      await db.execute(
        "UPDATE asset_inspection SET inspection_status = '취소', updated_at = now() WHERE asset_inspection_id = CAST(:id AS bigint)",
        { id },
      );
      return { inspectionStatus: '취소' };
    });
  }

  @Delete('/asset-inspections/:assetInspectionId')
  async deleteAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = idOf(req.params['assetInspectionId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT inspection_status AS "inspectionStatus" FROM asset_inspection WHERE asset_inspection_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'INSPECTION_NOT_FOUND', '실사정보를 찾을 수 없습니다.');
      }
      if (rows[0]['inspectionStatus'] !== '진행') {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '진행 중이 아닌 실사는 삭제할 수 없습니다.');
      }
      // 가정: 삭제는 상태 변경이 아닌 행 삭제
      await db.execute(
        'DELETE FROM asset_inspection WHERE asset_inspection_id = CAST(:id AS bigint)',
        { id },
      );
      return {};
    });
  }
}

