import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, TextInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [['진행', '진행'], ['완료', '완료'], ['취소', '취소']];

type Panel =
  | { kind: 'create' }
  | { kind: 'detail'; row: Row }
  | { kind: 'complete'; row: Row }
  | { kind: 'cancel'; row: Row }
  | { kind: 'delete'; row: Row };

export default function FnSfr02506Page({ role, notify }: PageProps) {
  const [planFilter, setPlanFilter] = useState<number | string>('');
  const [statusFilter, setStatusFilter] = useState('');
  const [applied, setApplied] = useState<{ plan: number | string; status: string }>({ plan: '', status: '' });
  const [page, setPage] = useState(0);
  const [panel, setPanel] = useState<Panel | null>(null);

  const [newPlan, setNewPlan] = useState<number | string>('');
  const [newAsset, setNewAsset] = useState<number | string>('');
  const [newResult, setNewResult] = useState('');
  const [doneResult, setDoneResult] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/asset-inspections', role, undefined, {
      assetInspectionPlanId: applied.plan,
      inspectionStatus: applied.status,
      page,
      size: SIZE,
    }),
    [applied, page, role],
  );
  const running = useData<Page>(
    () => call<Page>('GET', '/asset-inspections', role, undefined, { inspectionStatus: '진행', page: 0, size: 1 }),
    [role],
  );
  const finished = useData<Page>(
    () => call<Page>('GET', '/asset-inspections', role, undefined, { inspectionStatus: '완료', page: 0, size: 1 }),
    [role],
  );

  function refresh() {
    list.reload();
    running.reload();
    finished.reload();
  }

  function search() {
    setPage(0);
    setApplied({ plan: planFilter, status: statusFilter });
  }

  function reset() {
    setPlanFilter('');
    setStatusFilter('');
    setPage(0);
    setApplied({ plan: '', status: '' });
  }

  function openCreate() {
    setNewPlan('');
    setNewAsset('');
    setNewResult('');
    setPanel({ kind: 'create' });
  }

  async function create() {
    if (newPlan === '' || newAsset === '') {
      throw new Error('실사계획과 고정자산을 선택하세요.');
    }
    await call('POST', '/asset-inspections', role, {
      assetInspectionPlanId: newPlan,
      fixedAssetId: newAsset,
      inspectionResult: newResult,
    });
    notify('실사를 시작했습니다.');
    setPanel(null);
    refresh();
  }

  async function complete(row: Row) {
    await call('POST', '/asset-inspections/' + String(row.assetInspectionId) + '/complete', role, {
      inspectionResult: doneResult,
    });
    notify('실사를 완료 처리했습니다.');
    setPanel(null);
    refresh();
  }

  async function cancel(row: Row) {
    await call('POST', '/asset-inspections/' + String(row.assetInspectionId) + '/cancel', role, {});
    notify('실사를 취소했습니다.');
    setPanel(null);
    refresh();
  }

  async function remove(row: Row) {
    await call('DELETE', '/asset-inspections/' + String(row.assetInspectionId), role);
    notify('실사를 삭제했습니다.');
    setPanel(null);
    refresh();
  }

  const rows = list.data?.items ?? [];

  function renderPanel() {
    if (!panel) {
      return null;
    }
    if (panel.kind === 'create') {
      return (
        <Drawer title='실사 시작' onClose={() => setPanel(null)}>
          <Form onSubmit={create} submit='시작'>
            <Field label='실사계획' required>
              <LookupSelect table='asset_inspection_plan' role={role} value={newPlan} onChange={setNewPlan} />
            </Field>
            <Field label='고정자산' required>
              <LookupSelect table='fixed_asset' role={role} value={newAsset} onChange={setNewAsset} />
            </Field>
            <Field label='실사 결과' wide>
              <TextInput multiline value={newResult} onChange={setNewResult} />
            </Field>
          </Form>
        </Drawer>
      );
    }
    const row = panel.row;
    const inProgress = row.inspectionStatus === '진행';
    if (panel.kind === 'complete') {
      return (
        <Drawer title='실사 완료 처리' onClose={() => setPanel(null)}>
          <Form onSubmit={async () => {
            if (doneResult.trim() === '' && !row.inspectionResult) {
              throw new Error('실사 결과를 입력하세요.');
            }
            await complete(row);
          }} submit='완료 처리'>
            <Field label='실사 결과' required wide>
              <TextInput multiline value={doneResult} onChange={setDoneResult} />
            </Field>
          </Form>
        </Drawer>
      );
    }
    if (panel.kind === 'cancel') {
      return (
        <Drawer title='실사 취소' onClose={() => setPanel(null)}>
          <Form onSubmit={() => cancel(row)} submit='취소 처리' danger note='진행 중인 실사를 취소합니다.' />
        </Drawer>
      );
    }
    if (panel.kind === 'delete') {
      return (
        <Drawer title='실사 삭제' onClose={() => setPanel(null)}>
          <Form onSubmit={() => remove(row)} submit='삭제' danger note='진행 중인 실사를 삭제합니다.' />
        </Drawer>
      );
    }
    return (
      <Drawer title='실사 상세' onClose={() => setPanel(null)}>
        <Pairs items={[
          ['실사정보 ID', String(row.assetInspectionId)],
          ['실사계획', <RefName table='asset_inspection_plan' role={role} value={row.assetInspectionPlanId} />],
          ['고정자산', <RefName table='fixed_asset' role={role} value={row.fixedAssetId} />],
          ['실사 상태', <Badge value={row.inspectionStatus} />],
          ['실사 결과', String(row.inspectionResult ?? '')],
          ['실사 완료 일시', <DateText value={row.inspectedAt} time />],
        ]} />
        {inProgress && (
          <div>
            <button type='button' onClick={() => { setDoneResult(String(row.inspectionResult ?? '')); setPanel({ kind: 'complete', row }); }}>완료 처리</button>
            <button type='button' onClick={() => setPanel({ kind: 'cancel', row })}>취소</button>
            <button type='button' onClick={() => setPanel({ kind: 'delete', row })}>삭제</button>
          </div>
        )}
      </Drawer>
    );
  }

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>실사 현황</h2>
        <Tiles items={[
          ['진행 중', String(running.data?.total ?? 0)],
          ['완료', String(finished.data?.total ?? 0)],
        ]} />
      </section>
      <section className='box span-12'>
        <h2>실사 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='실사계획'>
            <LookupSelect table='asset_inspection_plan' role={role} value={planFilter} onChange={setPlanFilter} />
          </Field>
          <Field label='실사 상태'>
            <Select value={statusFilter} onChange={setStatusFilter} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type='button' onClick={openCreate}>실사 시작</button>
        </Band>
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          rows={rows}
          empty='실사 내역이 없습니다.'
          onRowClick={(row) => setPanel({ kind: 'detail', row })}
          columns={[
            { key: 'assetInspectionId', label: '실사정보 ID' },
            { key: 'assetInspectionPlanId', label: '실사계획', render: (r) => <RefName table='asset_inspection_plan' role={role} value={r.assetInspectionPlanId} /> },
            { key: 'fixedAssetId', label: '고정자산', render: (r) => <RefName table='fixed_asset' role={role} value={r.fixedAssetId} /> },
            { key: 'inspectionStatus', label: '실사 상태', render: (r) => <Badge value={r.inspectionStatus} /> },
            { key: 'inspectionResult', label: '실사 결과' },
            { key: 'inspectedAt', label: '실사 완료 일시', render: (r) => <DateText value={r.inspectedAt} time /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => r.inspectionStatus === '진행' ? (
                <span onClick={(e) => e.stopPropagation()}>
                  <button type='button' onClick={() => { setDoneResult(String(r.inspectionResult ?? '')); setPanel({ kind: 'complete', row: r }); }}>완료</button>
                  <button type='button' onClick={() => setPanel({ kind: 'cancel', row: r })}>취소</button>
                  <button type='button' onClick={() => setPanel({ kind: 'delete', row: r })}>삭제</button>
                </span>
              ) : null,
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {renderPanel()}
    </div>
  );
}
